OFF = .15   # mix.py plays the recording from 0.15 s
lines, dur, words, vos = [], {}, {}, {}
for i, (k, ws) in enumerate(T.items()):
    t0 = ws[0][1]
    lines.append({'id': k, 'text': DEV[k], 'roman': ' '.join(w[0] for w in ws), 'voice': 'elevenlabs (Monika Sogam), recorded', 'recorded': True, 'lang': 'hi'})
    dur[k] = round(ws[-1][2] - t0, 3); words[k] = [[w[0], round(w[1] - t0, 3), round(w[2] - t0, 3)] for w in ws]; vos[k] = round(t0 + OFF, 3)
for d in OUT:
    os.makedirs(os.path.join(d, 'voices-hi'), exist_ok=True)
    json.dump(lines, open(os.path.join(d, 'lines-hi.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    json.dump(dur, open(os.path.join(d, 'voices-hi', 'dur.json'), 'w'), indent=1)
    json.dump(words, open(os.path.join(d, 'voices-hi', 'words.json'), 'w', encoding='utf-8'), ensure_ascii=False)
print(json.dumps(vos))
